using Microsoft.EntityFrameworkCore;

// Cosmos DB EF Core 9 breaking-change fixes for existing documents.
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Default discriminator property renamed
        // from "Discriminator" to "$type" in EF Core 9.
        // Existing documents already use "Discriminator", so override the default
        // to keep reading them without a data migration.
        modelBuilder.Entity<Product>().HasDiscriminatorInJsonProperty("Discriminator");
    }

    // Breaking change 2: Synchronous Cosmos DB I/O now throws by default.
    // Replace sync calls like .ToList() / .First() with async equivalents:
    //   BEFORE: var items = db.Products.Where(p => p.Active).ToList();
    //   AFTER:  var items = await db.Products.Where(p => p.Active).ToListAsync();
    //
    // If you cannot migrate to async immediately, opt back in via connection string:
    //   "AccountEndpoint=...;AllowSynchronousIO=true"
    // or via DbContextOptionsBuilder:
    //   options.UseCosmos(endpoint, key, db, o => o.AllowSynchronousIO());
}

class Product
{
    public string Id { get; set; } = default!;
    public string Name { get; set; } = default!;
    public bool Active { get; set; }
}

